<script setup lang="ts">import {ref} from 'vue';import DetailFields from '../common/DetailFields.vue';import WorkItemForm from './WorkItemForm.vue';defineProps<{kind:'design'|'dev'|'bug';record:Record<string,unknown>}>();const emit=defineEmits<{save:[value:Record<string,unknown>];close:[]}>();const editing=ref(false);const fields=[{key:'title',label:'标题'},{key:'status',label:'状态'},{key:'ownerName',label:'负责人'},{key:'developer',label:'开发者'},{key:'priority',label:'优先级'},{key:'description',label:'描述'},{key:'createdAt',label:'创建时间'}];</script>
<template><div v-if="!editing"><DetailFields :record="record" :fields="fields"/><div class="form-actions"><button class="secondary" type="button" @click="emit('close')">关闭</button><button class="primary" type="button" @click="editing=true">编辑</button></div></div><WorkItemForm v-else :kind="kind" :model-value="record" @save="emit('save',$event)" @cancel="editing=false"/></template>
